fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let len = s.len();
    // P is the largest multiple of 3 not exceeding len
    let p = len - (len % 3);

    // Prepare the result vector with the same capacity as the input
    let mut res = Vec::with_capacity(len);

    // Process full triplets:
    // - for i % 3 == 0, take s[i+2]
    // - for i % 3 == 1 or 2, take s[i-1]
    for i in 0..p {
        if i % 3 == 0 {
            // safe because i+2 < p+2 ≤ len
            res.push(s[i + 2]);
        } else {
            // safe because i ≥ 1
            res.push(s[i - 1]);
        }
    }

    // Copy any remaining suffix of length len % 3 unchanged
    res.extend_from_slice(&s[p..]);

    res
}

